/* ============================================================
   CAREERS HERO — careers-hero.module.css
   ============================================================ */

.section {
  background-color: #082753;
  padding: 80px 5% 0;
  overflow: hidden;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Content block */
.content {
  text-align: center;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
  padding-bottom: 56px;
}

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(33, 207, 255, 0.12);
  border: 1px solid rgba(33, 207, 255, 0.25);
  border-radius: 100px;
  padding: 6px 18px;
  margin-bottom: 24px;
}

.badgeText {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* Heading */
.heading {
  color: #ffffff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: clamp(2.25rem, 5vw, 3.75rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 20px;
}

/* Subtitle */
.subtitle {
  color: rgba(255, 255, 255, 0.65);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 17px;
  font-weight: 400;
  line-height: 1.7;
  max-width: 640px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 40px;
}

/* CTA row */
.ctaRow {
  display: flex;
  align-items: center;
  justify-content: center;
}

.ctaButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 2rem;
  text-decoration: none;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
  transition: filter 0.2s, box-shadow 0.2s;
}

.ctaButton:hover {
  filter: brightness(1.1);
  box-shadow: 0 4px 24px rgba(33, 207, 255, 0.35);
}

/* Gallery row */
.galleryRow {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  align-items: flex-end;
}

.galleryCard {
  position: relative;
  border-radius: 16px 16px 0 0;
  overflow: hidden;
  height: 280px;
}

/* Subtle stagger/offset per card */
.galleryCard1 {
  transform: translateY(8px);
  height: 260px;
}

.galleryCard2 {
  height: 300px;
}

.galleryCard3 {
  transform: translateY(12px);
  height: 250px;
}

.galleryImage {
  object-fit: cover;
  object-position: center top;
  transition: transform 0.4s ease;
}

.galleryCard:hover .galleryImage {
  transform: scale(1.04);
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding: 60px 5% 0;
  }

  .galleryRow {
    gap: 12px;
  }

  .galleryCard {
    height: 220px;
  }

  .galleryCard1 {
    height: 200px;
  }

  .galleryCard2 {
    height: 240px;
  }

  .galleryCard3 {
    height: 190px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding: 56px 5% 0;
  }

  .content {
    padding-bottom: 40px;
  }

  .galleryRow {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .galleryCard3 {
    display: none;
  }

  .galleryCard1,
  .galleryCard2 {
    transform: none;
    height: 200px;
    border-radius: 12px 12px 0 0;
  }
}

/* ============================================================
