.section {
  background-color: #082753;
  padding: 80px 5% 88px;
  overflow: hidden;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Header */
.header {
  text-align: center;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.heading {
  color: #ffffff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
}

.subtitle {
  color: rgba(255, 255, 255, 0.65);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

.ctaButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 2rem;
  text-decoration: none;
  margin-top: 4px;
  transition: filter 0.2s, box-shadow 0.2s;
}

.ctaButton:hover {
  filter: brightness(1.1);
  box-shadow: 0 4px 24px rgba(33, 207, 255, 0.35);
}

/* Benchmarks grid — 3 columns x 2 rows */
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.benchCard {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.benchLabel {
  color: rgba(255, 255, 255, 0.75);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  margin: 0;
}

/* The gradient bar card */
.benchBar {
  border-radius: 16px;
  padding: 40px 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.benchPercentage {
  color: #ffffff;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 48px;
  font-weight: 700;
  line-height: 1;
}

/* Per-card gradient variants */
.card1 {
  background: linear-gradient(135deg, #21cfff 0%, #019ae6 100%);
}

.card2 {
  background: linear-gradient(135deg, #019ae6 0%, #0075c2 100%);
}

.card3 {
  background: linear-gradient(135deg, #0075c2 0%, #005fa3 100%);
}

.card4 {
  background: linear-gradient(135deg, #005fa3 0%, #094782 100%);
}

.card5 {
  background: linear-gradient(135deg, #094782 0%, #082060 100%);
}

.card6 {
  background: linear-gradient(135deg, #21cfff 0%, #019ae6 50%, #082060 100%);
  position: relative;
  overflow: hidden;
}

.card6::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  pointer-events: none;
}

